def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    r = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    coord = [0.0 for x in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0:
                q = d / (1.2 * (r[i] + r[j]))
                coord[i] += occ[j] / (1.0 + q ** 12)
    valid = [i for i in range(n) if r[i] is not None and r[i] > 0]
    total = sum(occ[i] for i in valid)
    return sum(occ[i] * coord[i] for i in valid) / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    r = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    coord = [0.0 for x in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0:
                q = d / (1.2 * (r[i] + r[j]))
                coord[i] += occ[j] / (1.0 + q ** 12)
    value = 0.0
    total = 0.0
    for i in range(n):
        p = props.get(sites[i].get('element')) or {}
        g = p.get('group')
        target = 0.0
        if p.get('Z') == 1:
            target = 1.0
        elif g == 13:
            target = 3.0
        elif g is not None and 14 <= g <= 17:
            target = 18.0 - g
        if target > 0 and r[i] is not None and r[i] > 0:
            value += occ[i] * max(0.0, target - coord[i])
            total += occ[i]
    return value / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    first = 0.0
    second = 0.0
    total = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        x = (props.get(element) or {}).get('first_ionization_energy_eV')
        if fraction is not None and fraction > 0 and x is not None:
            first += fraction * x
            second += fraction * x * x
            total += fraction
    if total <= 0:
        return 0.0
    mean = first / total
    return sqrt(max(0.0, second / total - mean * mean))

def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    value = 0.0
    total = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        shell = (props.get(element) or {}).get('pymatgen_valence_subshell')
        if fraction is not None and fraction > 0 and shell is not None and len(shell) == 2:
            l = shell[0]
            count = shell[1]
            if l is not None and count is not None:
                total += fraction
                if l == 3:
                    value += fraction * max(0.0, count)
    return value / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    occupied = 0.0
    spheres = 0.0
    for site in s.get('sites') or []:
        o = site.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        occupied += o
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        if r is not None and r > 0:
            spheres += o * r ** 3
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        volume = v * occupied if v is not None and v > 0 else 0.0
    return (4.0 * pi / 3.0) * spheres / volume if volume > 0 else 0.0
